//===----------------------------------------------------------------------===//
//
// Turn an MCInst into the four bytes of an RV32I instruction.
//
// The per-instruction bit shuffling is generated by TableGen from the
// Inst{...} assignments in RVMinInstrFormats.td.  This file only supplies the
// per-operand values and decides which fixup kind an unresolved expression
// needs.
//
//===----------------------------------------------------------------------===//

#include "RVMinFixupKinds.h"
#include "RVMinMCTargetDesc.h"
#include "llvm/MC/MCCodeEmitter.h"
#include "llvm/MC/MCContext.h"
#include "llvm/MC/MCExpr.h"
#include "llvm/MC/MCFixup.h"
#include "llvm/MC/MCInst.h"
#include "llvm/MC/MCInstrInfo.h"
#include "llvm/MC/MCRegisterInfo.h"
#include "llvm/MC/MCSubtargetInfo.h"
#include "llvm/Support/ErrorHandling.h"

using namespace llvm;

namespace {

class RVMinMCCodeEmitter : public MCCodeEmitter {
  MCContext &Ctx;
  const MCInstrInfo &MCII;

public:
  RVMinMCCodeEmitter(MCContext &Ctx, const MCInstrInfo &MCII)
      : Ctx(Ctx), MCII(MCII) {}

  void encodeInstruction(const MCInst &MI, SmallVectorImpl<char> &CB,
                         SmallVectorImpl<MCFixup> &Fixups,
                         const MCSubtargetInfo &STI) const override;

  uint64_t getBinaryCodeForInstr(const MCInst &MI,
                                 SmallVectorImpl<MCFixup> &Fixups,
                                 const MCSubtargetInfo &STI) const;

  uint64_t getMachineOpValue(const MCInst &MI, const MCOperand &MO,
                             SmallVectorImpl<MCFixup> &Fixups,
                             const MCSubtargetInfo &STI) const;
};

} // end anonymous namespace

uint64_t RVMinMCCodeEmitter::getMachineOpValue(
    const MCInst &MI, const MCOperand &MO, SmallVectorImpl<MCFixup> &Fixups,
    const MCSubtargetInfo &STI) const {
  if (MO.isReg())
    return Ctx.getRegisterInfo()->getEncodingValue(MO.getReg());

  if (MO.isImm())
    return static_cast<uint64_t>(MO.getImm());

  assert(MO.isExpr() && "unexpected operand kind");

  // A symbolic operand has no value yet: record a fixup and let the assembler
  // backend patch the immediate bits once layout is known.
  unsigned Kind;
  switch (MI.getOpcode()) {
  case RVMin::BEQ:
  case RVMin::BNE:
  case RVMin::BLT:
  case RVMin::BGE:
  case RVMin::BLTU:
  case RVMin::BGEU:
    Kind = rvmin::fixup_rvmin_branch;
    break;
  case RVMin::JAL:
    Kind = rvmin::fixup_rvmin_jal;
    break;
  default:
    Kind = rvmin::fixup_rvmin_32;
    break;
  }

  bool IsPCRel = Kind == rvmin::fixup_rvmin_branch ||
                 Kind == rvmin::fixup_rvmin_jal;
  Fixups.push_back(
      MCFixup::create(0, MO.getExpr(), (MCFixupKind)Kind, IsPCRel));
  return 0;
}

void RVMinMCCodeEmitter::encodeInstruction(const MCInst &MI,
                                           SmallVectorImpl<char> &CB,
                                           SmallVectorImpl<MCFixup> &Fixups,
                                           const MCSubtargetInfo &STI) const {
  if (MCII.get(MI.getOpcode()).isPseudo())
    report_fatal_error("RVMin: cannot encode pseudo instruction " +
                       MCII.getName(MI.getOpcode()));

  uint64_t Bits = getBinaryCodeForInstr(MI, Fixups, STI);

  // RV32I is little-endian: the lowest-addressed byte holds Inst[7:0].
  for (unsigned I = 0; I != 4; ++I)
    CB.push_back(static_cast<char>((Bits >> (8 * I)) & 0xff));
}

MCCodeEmitter *llvm::createRVMinMCCodeEmitter(MCContext &Ctx,
                                              const MCInstrInfo &MII) {
  return new RVMinMCCodeEmitter(Ctx, MII);
}

#include "RVMinGenMCCodeEmitter.inc"
